-- ADDRESS Q1-Q20: initialize independent working data, never immutable publications.
BEGIN;
LOCK TABLE "Site", "PageTemplate", "PageTemplateBlock", "Page", "SeoTemplate", "ContentRevision", "AuditEvent" IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE _address_sites ON COMMIT DROP AS
SELECT s."id", s."workingRevision"+1 AS revision FROM "Site" s JOIN "Provider" p ON p."id"=s."providerId"
WHERE p."slug"='domru' AND NOT EXISTS (SELECT 1 FROM "PageTemplate" t WHERE t."siteId"=s."id" AND t."kind"='CITY_ADDRESS_CHECK');
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM "Page" p JOIN _address_sites s ON s."id"=p."siteId" WHERE p."slug"='proverka-podklyucheniya-k-domru-po-adresu')
 OR EXISTS (SELECT 1 FROM "Tariff" t JOIN "City" c ON c."id"=t."cityId" JOIN _address_sites s ON s."id"=c."siteId" WHERE t."slug"='proverka-podklyucheniya-k-domru-po-adresu')
 THEN RAISE EXCEPTION 'ADDRESS canonical slug is occupied; preserve existing content and resolve collision'; END IF;
END $$;
INSERT INTO "PageTemplate" ("id","siteId","kind","status","titleTemplate","content","createdAt","updatedAt")
SELECT 'address_template_'||md5(s."id"),s."id",'CITY_ADDRESS_CHECK','PUBLISHED','Проверка подключения Дом.ру по адресу в {CITY_NAME_PREPOSITIONAL}',
'{"addressCheckCompositionVersion":"1.0.0","addressCheckImplementationVersion":"address-page-v1"}'::jsonb,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM _address_sites s;
INSERT INTO "PageTemplateBlock" ("id","templateId","blockType","position","visible","data","source")
SELECT 'address_block_'||md5(t."id"||b.kind),t."id",b.kind,b.position,true,b.data,'migration:0064:address-page'
FROM _address_sites s JOIN "PageTemplate" t ON t."siteId"=s."id" AND t."kind"='CITY_ADDRESS_CHECK'
CROSS JOIN (VALUES (10,'address.intro',$address${"title": "Проверка подключения Дом.ру в {CITY_NAME_PREPOSITIONAL}", "intro": "Проверьте, доступен ли Дом.ру в вашем доме."}$address$::jsonb),
(20,'address.check',$address${"eyebrow": "ПРОВЕРКА ПОДКЛЮЧЕНИЯ", "title": "Введите адрес подключения", "intro": "Выберите город, улицу и дом из подсказок.", "addressLabel": "Адрес подключения", "addressPlaceholder": "Город, улица, дом", "checkButtonText": "Проверить адрес", "reassuranceText": "Проверка бесплатная и ни к чему не обязывает.", "image": "/images/general-home/address-house.png", "imageAlt": "Дом и отметка проверки подключения на карте", "imageBadgeText": "Проверим\nза пару секунд", "helpEyebrow": "ПОМОЖЕМ С ПОДКЛЮЧЕНИЕМ", "helpTitle": "Подберем тариф\nи объясним условия", "callbackButtonText": "Заказать звонок"}$address$::jsonb),
(30,'address.results',$address${"title": "Что означает результат проверки", "intro": "После проверки выбранного дома вы получите один из трёх результатов.", "items": {"available": {"title": "Дом.ру доступен", "text": "Проверка подтвердила возможность подключения Дом.ру в выбранном доме.", "nextLabel": "Что дальше", "nextText": "Продолжите оформление заявки. Тариф и условия уточнит специалист."}, "alternatives": {"title": "Найдены другие провайдеры", "text": "Дом.ру не найден, но по адресу есть предложения других провайдеров.", "nextLabel": "Что дальше", "nextText": "Перейдите к альтернативным предложениям из результата проверки."}, "none": {"title": "Предложений не найдено", "text": "По выбранному адресу предложений провайдеров не найдено.", "nextLabel": "Что дальше", "nextText": "Уточните адрес и повторите проверку или обратитесь за консультацией."}}, "noteTitle": "Нет адреса или возникла ошибка?", "noteText": "Это ещё не результат проверки. Уточните адрес или повторите попытку позже."}$address$::jsonb),
(40,'address.tariffs',$address${"title": "Популярные тарифы в {CITY_NAME_PREPOSITIONAL}", "intro": "Это предложения города. Доступность выбранного тарифа в вашем доме нужно проверить по адресу.", "connectButtonText": "Подключить", "detailsButtonText": "Подробнее", "allTariffsLinkText": "Все тарифы в {CITY_NAME_PREPOSITIONAL}"}$address$::jsonb),
(50,'address.connection_steps',$address${"title": "Как подключить Дом.ру", "intro": "Четыре понятных шага от обращения до работающего интернета.", "steps": {"request": {"title": "Оставьте заявку", "text": "Позвоните в отдел подключений или оставьте заявку на сайте."}, "appointment": {"title": "Согласование визита", "text": "Согласуйте с оператором удобное время приезда мастера."}, "installation": {"title": "Подключение и настройка", "text": "Мастер подключит услуги и настроит оборудование."}, "confirmation": {"title": "Оформление и проверка", "text": "Специалист оформит договор и проверит работу услуг."}}, "applyButtonText": "Оставить заявку"}$address$::jsonb),
(60,'address.benefits',$address${"title": "Основные преимущества подключения Дом.ру", "items": {"speed": {"title": "Высокая скорость интернета", "text": "Смотрите видео в 4K, работайте из дома и загружайте большие файлы. Выбирайте скорость под свои задачи."}, "fiber": {"title": "Оптоволоконная сеть", "text": "Дом.ру использует проводную оптоволоконную инфраструктуру для подключения жилых домов. Технология доступа зависит от адреса."}, "wifi6": {"title": "Домашний Wi-Fi 6", "text": "Роутеры Дом.ру Wave помогают организовать беспроводную сеть для смартфонов, ноутбуков, телевизоров и умных устройств."}, "movix": {"title": "Фильмы и сериалы в Movix", "text": "Смотрите телеканалы, фильмы и сериалы в одном сервисе. Выбирайте подписки с учетом своих интересов."}, "connection": {"title": "Удобное оформление подключения", "text": "Выберите тариф, проверьте возможность подключения по адресу и согласуйте удобное время визита мастера."}, "support": {"title": "Поддержка абонентов 24/7", "text": "Обращайтесь за помощью по вопросам домашнего интернета, телевидения и оборудования в любое время суток."}}}$address$::jsonb),
(70,'address.help',$address${"title": "Поможем выбрать тариф и подключить Дом.ру", "intro": "Специалист поможет подобрать тариф, объяснит стоимость и условия подключения.", "formTitle": "Перезвоним вам", "phoneLabel": "Телефон для обратного звонка", "phonePlaceholder": "+7 (___) ___-__-__", "submitButtonText": "Заказать звонок"}$address$::jsonb),
(80,'address.faq',$address${"title": "Вопросы и ответы", "items": [{"question": "Какие данные нужны для проверки адреса?", "answer": "Выберите город, улицу и дом из подсказок. Если у дома есть корпус или строение, выберите адрес с нужным уточнением. Проверка относится к конкретному дому."}, {"question": "Можно ли проверить адрес без номера телефона?", "answer": "Да. Для проверки доступности выберите адрес — телефон на этом шаге не требуется. Если Дом.ру доступен и вы решите оставить заявку на подключение, номер понадобится для связи со специалистом."}, {"question": "Что делать, если адреса нет в подсказках?", "answer": "Проверьте город и написание улицы, уточните номер дома, корпус или строение. Попробуйте выбрать адрес из подсказок еще раз. Если адрес не появился, воспользуйтесь консультацией. Отсутствие адреса в подсказках не подтверждает отсутствие подключения."}, {"question": "Что делать, если проверка завершилась ошибкой?", "answer": "Повторите попытку позже. Пока проверка не завершена, вывод о доступности сделать нельзя. Если ошибка повторяется, обратитесь за консультацией."}, {"question": "Достаточно ли карты покрытия для проверки?", "answer": "Нет. Карта показывает общую зону обслуживания, но не подтверждает подключение конкретного дома. Проверьте точный адрес в форме. Подборка тарифов города также не означает, что все предложения доступны в вашем доме."}, {"question": "Можно ли проверить частный дом?", "answer": "Возможность подключения частного дома нужно уточнять по его точному адресу. Если адрес доступен в подсказках, выберите его и запустите проверку. Если найти дом не удалось, воспользуйтесь консультацией."}]}$address$::jsonb)) AS b(position,kind,data);
INSERT INTO "Page" ("id","siteId","cityId","type","title","slug","status","templateId","createdAt","updatedAt")
SELECT 'address_page_'||md5(c."id"),c."siteId",c."id",'ADDRESS_CHECK',t."titleTemplate",'proverka-podklyucheniya-k-domru-po-adresu','PUBLISHED',t."id",CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM "City" c JOIN _address_sites s ON s."id"=c."siteId" JOIN "PageTemplate" t ON t."siteId"=s."id" AND t."kind"='CITY_ADDRESS_CHECK';
INSERT INTO "SeoTemplate" ("id","siteId","kind","titleTemplate","descriptionTemplate","indexState","createdAt","updatedAt")
SELECT 'address_seo_'||md5(s."id"),s."id",'CITY_ADDRESS_CHECK','Проверка подключения Дом.ру по адресу в {CITY_NAME_PREPOSITIONAL}',
'Проверьте, доступен ли Дом.ру по вашему адресу в {CITY_NAME_PREPOSITIONAL}. Выберите дом, узнайте результат проверки и посмотрите тарифы города','INDEX',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM _address_sites s;
UPDATE "Site" s SET "workingRevision"=a.revision,"updatedAt"=CURRENT_TIMESTAMP FROM _address_sites a WHERE a."id"=s."id";
INSERT INTO "ContentRevision" ("id","siteId","entityType","entityId","entityRevision","siteRevision","action","snapshot","changedFields","source","createdAt")
SELECT 'address_template_revision_'||md5(t."id"),t."siteId",'PAGE_TEMPLATE',t."id",1,s.revision,'CREATE',
to_jsonb(t)||jsonb_build_object('blocks',(SELECT jsonb_agg(to_jsonb(b) ORDER BY b."position") FROM "PageTemplateBlock" b WHERE b."templateId"=t."id")),
'["titleTemplate","content","blocks"]'::jsonb,'migration:0064:address-page',CURRENT_TIMESTAMP
FROM _address_sites s JOIN "PageTemplate" t ON t."siteId"=s."id" AND t."kind"='CITY_ADDRESS_CHECK';
INSERT INTO "ContentRevision" ("id","siteId","entityType","entityId","entityRevision","siteRevision","action","snapshot","changedFields","source","createdAt")
SELECT 'address_page_revision_'||md5(p."id"),p."siteId",'PAGE',p."id",1,s.revision,'CREATE',to_jsonb(p),'["templateId","slug","status"]'::jsonb,'migration:0064:address-page',CURRENT_TIMESTAMP
FROM _address_sites s JOIN "Page" p ON p."siteId"=s."id" AND p."slug"='proverka-podklyucheniya-k-domru-po-adresu';
INSERT INTO "AuditEvent" ("id","siteId","siteRevision","entityType","entityId","action","changedFields","changes","source","createdAt")
SELECT 'address_audit_'||md5(s."id"),s."id",s.revision,'SITE',s."id",'UPDATE','["pageTemplates","pages","seoTemplates"]'::jsonb,
'{"initializedAddressPage":true,"compositionVersion":"1.0.0","preservedPublishedSnapshots":true}'::jsonb,'migration:0064:address-page',CURRENT_TIMESTAMP FROM _address_sites s;
COMMIT;
